{
  "version": 1,
  "violations": []
}

/**
 * Pre-CLI Mobile Test Automation Setup (generic preCliJSAction)
 *
 * Designed for story/bug trigger tickets that have linked Test Case tickets
 * via "is tested by" relationship. Prepares the test automation repository
 * for the AI agent to write and run mobile tests.
 *
 * Steps:
 * 1. Move trigger ticket to In Development
 * 2. Fetch ALL linked Test Case tickets ("is tested by" relationship)
 * 3. Write linked test case details to input/{KEY}/linked_test_cases.md
 * 4. Create / checkout test/{KEY} branch in the target test automation repo
 * 5. Download latest successful iOS simulator build artifact from Bitrise
 *    and write the .app path to input/{KEY}/app_info.md
 *
 * Used by: project-specific test automation agent configs
 * Requires: customParams.targetRepository.workingDir pointing to the
 *           checked-out test automation repository.
 * Optional: customParams.bitriseBuild.appSlug + workflowId to enable
 *           artifact download. Also needs customParams.featurePR to
 *           resolve the feature branch from the Jira ticket's linked PR.
 */

var configLoader = require('./configLoader.js');
var prHelper = require('./common/pullRequest.js');
var mergeState = require('./common/mergeState.js');
const { STATUSES } = require('./config.js');
var trackersModule = require('./common/trackers.js');
var setupHelpers = require('./preCliMobileTestAutomationSetupHelpers.js');

// Canonical copy (gh-823/gh-912): the warning:/note: line filter lives in
// common/pullRequest.js once — this delegate keeps every local call site.
function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

/** Run a git / shell command inside the test automation repo working directory. */
function runInRepo(command, workingDir) {
    return cli_execute_command({ command: command, workingDirectory: workingDir });
}

/**
 * Checkout (or create) test/{ticketKey} branch in the automation repo.
 * Syncs existing branch from origin/<baseBranch> via rebase, falling back to merge.
 */
function checkoutAutomationBranch(ticketKey, config) {
    var workingDir = config.workingDir;
    var baseBranch = (config.git && config.git.baseBranch) || 'main';
    var branchName = 'test/' + ticketKey;

    console.log('Setting up automation repo branch:', branchName, 'in', workingDir);

    try {
        runInRepo('git config user.name "' + config.git.authorName + '"', workingDir);
        runInRepo('git config user.email "' + config.git.authorEmail + '"', workingDir);
    } catch (e) {
        console.warn('Failed to configure git author:', e);
    }

    try {
        var targetedFetch = prHelper.buildTargetedOriginFetchCommand(
            [branchName, (config.git && config.git.baseBranch) || 'main']);
        if (targetedFetch) runInRepo(targetedFetch, workingDir);
    } catch (e) {
        console.warn('Could not fetch remote branches:', e);
    }

    var localBranches = cleanCommandOutput(
        runInRepo('git branch --list "' + branchName + '"', workingDir) || ''
    );

    function syncWithBase() {
        // gh-761: never start a rebase or merge on top of an unconcluded
        // merge (MERGE_HEAD present — e.g. the agent left a conflicted
        // base-branch merge unresolved). The rebase would fail, and the
        // merge fallback below would then fail with "You have not concluded
        // your merge" and SILENTLY `git merge --abort` the agent's in-flight
        // resolution — destroying work this setup step did not start. Leave
        // the tree exactly as the agent left it; the agent concludes (or
        // aborts) the merge itself.
        if (mergeState.isMergeInProgress(runInRepo, workingDir)) {
            console.warn('⚠️ MERGE_HEAD exists in ' + workingDir +
                ' — a merge is already in progress; skipping base-branch sync (rebase/merge on top of it would finalize or abort the in-flight merge)');
            return;
        }
        try {
            runInRepo('git rebase origin/' + baseBranch, workingDir);
            console.log('✅ Rebase succeeded');
        } catch (rebaseErr) {
            console.warn('Rebase failed, falling back to merge:', rebaseErr);
            try { runInRepo('git rebase --abort', workingDir); } catch (_) {}
            try {
                runInRepo('git merge origin/' + baseBranch + ' --no-edit', workingDir);
                console.log('✅ Merged base into branch');
            } catch (mergeErr) {
                console.warn('Merge also failed:', mergeErr);
                try { runInRepo('git merge --abort', workingDir); } catch (_) {}
            }
        }
    }

    if (localBranches.trim()) {
        console.log('Branch exists locally, syncing from', baseBranch + ':', branchName);
        runInRepo('git checkout ' + branchName, workingDir);
        syncWithBase();
    } else {
        var remoteBranchExists = false;
        try {
            // gh-912: decide on a real refs/heads/<branch> ref line — a
            // warning-only capture (central-mode insteadOf origin, git ≥
            // 2.54) must classify as "branch absent".
            remoteBranchExists = prHelper.remoteBranchExists(runInRepo, workingDir, branchName);
        } catch (e) {
            console.warn('Error checking remote branches:', e);
        }

        if (remoteBranchExists) {
            console.log('Branch exists on remote, checking out:', branchName);
            runInRepo('git checkout -b ' + branchName + ' origin/' + branchName, workingDir);
            syncWithBase();
        } else {
            console.log('Creating new branch from', baseBranch + ':', branchName);
            runInRepo('git checkout ' + baseBranch, workingDir);
            runInRepo('git pull origin ' + baseBranch, workingDir);
            runInRepo('git checkout -b ' + branchName, workingDir);
        }
    }

    console.log('✅ Automation branch ready:', branchName);
}

/** Run every linked-TC search (primary JQL, then the broader fallback). */
function searchLinkedTestCases(ticketKey, tracker) {
    var linkedTCs = [];

    // Primary: "is tested by" relationship
    try {
        // JQL text: provider-specific query (WIQL on ado)
        linkedTCs = tracker.searchIssues(
            setupHelpers.buildPrimaryLinkedTcJql(ticketKey),
            setupHelpers.linkedTcSearchOptions());
    } catch (e) {
        console.warn('Primary JQL failed, trying fallback:', e);
    }

    // Fallback: any linked test cases (broader search)
    if (!linkedTCs || linkedTCs.length === 0) {
        try {
            // JQL text: provider-specific query (WIQL on ado)
            linkedTCs = tracker.searchIssues(
                setupHelpers.buildFallbackLinkedTcJql(ticketKey),
                setupHelpers.linkedTcSearchOptions());
        } catch (e2) {
            console.warn('Fallback JQL also failed:', e2);
        }
    }

    return linkedTCs;
}

/** Fetch one TC's full ticket and append its recent run comments to lines. */
function appendTcRunComments(lines, tc, tracker) {
    // Fetch full ticket for comments (run history, prior failures)
    try {
        var tcDetails = tracker.getIssue(tc.key);
        var tcFields = tcDetails && tcDetails.fields || {};
        var commentBlock = tcFields.comment;
        var comments = commentBlock && commentBlock.comments || [];

        Array.prototype.push.apply(lines, setupHelpers.formatRecentTcComments(comments));
    } catch (ce) {
        console.warn('Could not fetch comments for', tc.key + ':', ce);
    }
}

/** Build the linked_test_cases.md body for non-empty search results. */
function buildLinkedTestCasesMarkdown(ticketKey, linkedTCs, tracker) {
    var lines = setupHelpers.buildLinkedTestCasesHeader(ticketKey);

    for (var i = 0; i < linkedTCs.length; i++) {
        var tc = linkedTCs[i];
        Array.prototype.push.apply(lines, setupHelpers.formatLinkedTcEntry(tc));
        appendTcRunComments(lines, tc, tracker);
    }

    return lines;
}

/** Fetch all Test Cases linked via "is tested by" and write to input folder. */
function fetchLinkedTestCases(ticketKey, folder, tracker) {
    var linkedTCs = searchLinkedTestCases(ticketKey, tracker);

    if (!linkedTCs || linkedTCs.length === 0) {
        console.log('No linked test cases found for', ticketKey);
        file_write(folder + '/linked_test_cases.md',
            '# Linked Test Cases\n\nNo linked Test Case tickets found for ' + ticketKey + '.\n');
        return 0;
    }

    console.log('Found', linkedTCs.length, 'linked test case(s)');

    file_write(folder + '/linked_test_cases.md',
        buildLinkedTestCasesMarkdown(ticketKey, linkedTCs, tracker).join('\n'));
    console.log('✅ Written linked_test_cases.md (' + linkedTCs.length + ' TCs)');
    return linkedTCs.length;
}

function parseMcpResult(result) {
    if (!result) return null;
    if (typeof result === 'string') {
        try { return JSON.parse(result); } catch (e) { return null; }
    }
    return result;
}

/**
 * Find the feature branch for ticketKey from open PRs in the featurePR repo.
 * Returns the branch name string, or null if not found.
 */
function findFeatureBranch(ticketKey, featurePR) {
    if (!featurePR || !featurePR.owner || !featurePR.repo) return null;
    try {
        var raw = github_list_prs({
            workspace: featurePR.owner,
            repository: featurePR.repo,
            state: 'open'
        });
        var match = setupHelpers.decideFeatureBranchFromPrs(
            setupHelpers.parseMcpPrList(parseMcpResult(raw)), ticketKey);
        if (match.found) {
            console.log('✅ Found feature branch:', match.branch, '(PR #' + match.prNumber + ')');
            return match.branch;
        }
        console.log('No open PR found for', ticketKey, 'in', featurePR.owner + '/' + featurePR.repo);
    } catch (e) {
        console.warn('Could not list PRs for feature branch lookup:', e);
    }
    return null;
}

/** Log the branch-match outcome of the build listing (matched vs fallback). */
function logBranchMatchOutcome(branch, branchDecision, successBuilds) {
    if (branch && successBuilds.length > 0) {
        if (branchDecision.matched) {
            console.log('✅ Found', branchDecision.builds.length, 'build(s) matching branch', branch);
        } else {
            console.warn('⚠️ No builds found with commit message matching "' + branch + '".',
                'Using latest successful build instead. Available builds:');
            var warnLines = setupHelpers.formatBuildsWarningList(successBuilds);
            for (var wi = 0; wi < warnLines.length; wi++) {
                console.warn(warnLines[wi]);
            }
        }
    }
}

/**
 * List recent builds, narrow to successful/branch-matched, and return the
 * build slug. Throws the canonical wrapped error on listing failure.
 */
function resolveBitriseBuildSlug(appSlug, workflowId, branch) {
    try {
        // Bitrise trigger branch is always "main" (for YAML source), so we
        // cannot filter by feature branch. Instead, list recent builds for the
        // workflow and match by commit message which contains the feature branch.
        var buildsResult = parseMcpResult(bitrise_list_builds({
            appSlug: appSlug,
            workflowId: workflowId,
            limit: 20
        }));
        var builds = setupHelpers.parseMcpDataList(buildsResult);

        // status=1 means success in Bitrise API
        var successBuilds = setupHelpers.decideSuccessfulBuilds(builds);

        // If we have a feature branch, find the build whose commit message
        // mentions it (e.g. "PROJ-6818 — iOS build for bug/PROJ-6818")
        var branchDecision = setupHelpers.decideBranchBuilds(successBuilds, branch);
        logBranchMatchOutcome(branch, branchDecision, successBuilds);

        var buildDecision = setupHelpers.decideBuildSlug(branchDecision.builds, workflowId);
        console.log('✅ Found build #' + buildDecision.buildNumber + ' slug:', buildDecision.slug);
        return buildDecision.slug;
    } catch (e) {
        throw new Error('Failed to list Bitrise builds: ' + e);
    }
}

/** Pick the app artifact of a build. Returns { slug, title } or null. */
function resolveBitriseArtifact(appSlug, buildSlug) {
    try {
        var artifacts = parseMcpResult(bitrise_list_build_artifacts({ appSlug: appSlug, buildSlug: buildSlug }));
        var artifactList = setupHelpers.parseMcpDataList(artifacts);
        // Find .zip or .app artifact
        var appArtifact = setupHelpers.decideAppArtifact(artifactList);
        if (!appArtifact) {
            console.warn('No artifacts found for build', buildSlug);
            return null;
        }
        console.log('📦 Found artifact:', appArtifact.title, '(' + Math.round((appArtifact.file_size_bytes || 0) / 1024 / 1024) + ' MB)');
        return { slug: appArtifact.slug, title: appArtifact.title };
    } catch (e) {
        console.warn('Failed to list artifacts:', e);
        return null;
    }
}

/** Get the expiring download URL of an artifact (null when unavailable). */
function resolveArtifactDownloadUrl(appSlug, buildSlug, artifactSlug) {
    try {
        var artifactDetails = parseMcpResult(bitrise_get_build_artifact({
            appSlug: appSlug,
            buildSlug: buildSlug,
            artifactSlug: artifactSlug
        }));
        var downloadUrl = artifactDetails && artifactDetails.data && artifactDetails.data.expiring_download_url;
        if (!downloadUrl) {
            console.warn('No download URL in artifact response');
            return null;
        }
        return downloadUrl;
    } catch (e) {
        console.warn('Failed to get artifact download URL:', e);
        return null;
    }
}

/**
 * Download the artifact zip into the input folder and unzip it there.
 * Removes the zip after a successful unzip (non-fatal if that fails).
 * Returns false when the download/unzip step failed.
 */
function downloadAndUnzipArtifact(downloadUrl, folder) {
    var appDir = folder + '/app';
    var zipPath = folder + '/app.zip';
    try {
        cli_execute_command({ command: 'bash -c "mkdir -p \'' + appDir + '\'"' });
        console.log('⬇️  Downloading artifact to', zipPath, '...');
        cli_execute_command({
            command: 'curl -s -L "' + downloadUrl + '" -o "' + zipPath + '"'
        });
        console.log('📂 Unzipping to', appDir, '...');
        cli_execute_command({ command: 'unzip -o "' + zipPath + '" -d "' + appDir + '"' });
    } catch (e) {
        console.warn('Failed to download/unzip artifact:', e);
        return false;
    }
    try { cli_execute_command({ command: 'rm -f "' + zipPath + '"' }); } catch (_) {}
    return true;
}

/** Locate the .app bundle under the unzip dir (null when not found). */
function locateAppBundlePath(appDir) {
    try {
        var findResult = cleanCommandOutput(
            cli_execute_command({ command: 'find "' + appDir + '" -name "*.app" -maxdepth 3 -type d' })
        );
        var appPath = setupHelpers.parseFindAppResult(findResult);
        if (appPath) {
            console.log('✅ iOS .app found:', appPath);
        } else if (findResult) {
            // Filter out .dSYM, pick first real .app
            console.warn('Could not find .app bundle after unzip');
        }
        return appPath;
    } catch (e) {
        console.warn('Failed to locate .app bundle:', e);
        return null;
    }
}

/** Write app_info.md for the agent prompt. */
function writeAppInfoFile(folder, workflowId, buildSlug, artifactTitle, branch, appPath) {
    var infoLines = setupHelpers.buildAppInfoMarkdown(
        workflowId, buildSlug, artifactTitle, branch, appPath, folder + '/app');
    file_write(folder + '/app_info.md', infoLines.join('\n'));
    console.log('✅ Written app_info.md' + (appPath ? ' → ' + appPath : ''));
}

/**
 * Download the latest successful iOS simulator build artifact from Bitrise.
 *
 * Looks for the most recent successful build of workflowId on the feature branch,
 * downloads the .zip artifact, unzips it, finds the .app bundle, and writes
 * input/{KEY}/app_info.md with the path for the agent prompt to use.
 *
 * @param {string} ticketKey
 * @param {string} folder       - input folder path, e.g. "input/PROJ-6618"
 * @param {object} bitriseBuild - { appSlug, workflowId }
 * @param {string} branch       - feature branch name (may be null → any branch)
 * @param {string} workingDir   - working directory for cli commands
 */
function downloadBitriseApp(ticketKey, folder, bitriseBuild, branch, workingDir) {
    if (!setupHelpers.decideBitriseBuildConfigured(bitriseBuild)) {
        console.log('No bitriseBuild config — skipping artifact download');
        return;
    }

    var appSlug = bitriseBuild.appSlug;
    var workflowId = bitriseBuild.workflowId;
    console.log('🔍 Looking for latest successful', workflowId, 'build' +
        (branch ? ' on branch ' + branch : '') + ' ...');

    // Find latest successful build
    var buildSlug = resolveBitriseBuildSlug(appSlug, workflowId, branch);

    // List artifacts
    var artifact = resolveBitriseArtifact(appSlug, buildSlug);
    if (!artifact) {
        return;
    }

    // Get expiring download URL
    var downloadUrl = resolveArtifactDownloadUrl(appSlug, buildSlug, artifact.slug);
    if (!downloadUrl) {
        return;
    }

    // Download and unzip to input folder
    if (!downloadAndUnzipArtifact(downloadUrl, folder)) {
        return;
    }

    // Find the .app bundle path
    var appPath = locateAppBundlePath(folder + '/app');

    // Write app_info.md for the agent prompt
    writeAppInfoFile(folder, workflowId, buildSlug, artifact.title, branch, appPath);
    return appPath || null;
}

/**
 * Install the .app on the already-booted iOS simulator.
 * The simulator is booted in a prior Bitrise step; SIMULATOR_UDID is in env.
 *
 * @param {string} appPath - absolute path to the .app bundle
 * @param {string} folder  - input folder for writing updated app_info.md
 * @param {string} [appId] - bundle identifier (e.g. com.example.internal.business.app)
 */
function installAppOnSimulator(appPath, folder, appId) {
    if (!appPath) {
        console.warn('No app path — skipping simulator install');
        return;
    }

    // Read SIMULATOR_UDID from env (set by the "Boot iOS simulator" Bitrise step)
    var udid = null;
    try {
        udid = cleanCommandOutput(
            cli_execute_command({ command: 'bash -c "echo $SIMULATOR_UDID"' })
        );
    } catch (_) {}

    if (!udid) {
        // Fallback: find already-booted simulator
        try {
            var simList = cleanCommandOutput(
                cli_execute_command({ command: 'xcrun simctl list devices booted' })
            );
            udid = setupHelpers.matchBootedSimulatorUdid(simList);
        } catch (e) {
            console.warn('Could not list booted simulators:', e);
        }
    }

    if (!udid) {
        console.warn('⚠️ No booted simulator found — agent will write flows only');
        return;
    }

    // Install app on the booted simulator
    try {
        cli_execute_command({ command: 'xcrun simctl install "' + udid + '" "' + appPath + '"' });
        console.log('✅ App installed on simulator:', udid);
    } catch (e) {
        console.error('Failed to install app on simulator:', e);
        return;
    }

    // Append simulator info to app_info.md
    var resolvedAppId = setupHelpers.defaultAppId(appId);
    try {
        var simInfo = setupHelpers.buildSimulatorInfoMarkdown(udid, resolvedAppId);
        var existing = '';
        try { existing = file_read({ path: folder + '/app_info.md' }) || ''; } catch (_) {}
        file_write(folder + '/app_info.md', existing + '\n' + simInfo.join('\n'));
    } catch (e) {
        console.warn('Failed to update app_info.md with simulator info:', e);
    }
}


function action(params) {
    try {
        var actualParams = params.inputFolderPath ? params : (params.jobParams || params);
        var folder = actualParams.inputFolderPath;
        var ticketKey = folder.split('/').pop();
        var config = configLoader.loadProjectConfig(params.jobParams || params);
        var customParams = (params.jobParams || params).customParams || {};
        var tracker = trackersModule.createTracker(config, customParams);

        console.log('=== Mobile test automation setup for:', ticketKey, '===');

        // Step 1: Move trigger ticket to In Development
        try {
            tracker.moveToStatus(ticketKey, STATUSES.IN_DEVELOPMENT);
            console.log('✅ Moved', ticketKey, 'to In Development');
        } catch (e) {
            console.warn('Failed to move ticket to In Development:', e);
        }

        // Step 2: Fetch linked Test Cases and write to input folder
        try {
            fetchLinkedTestCases(ticketKey, folder, tracker);
        } catch (e) {
            console.error('Failed to fetch linked test cases:', e);
        }

        // Step 3: Checkout test/{KEY} branch in automation repo
        if (config.workingDir) {
            try {
                checkoutAutomationBranch(ticketKey, config);
            } catch (e) {
                console.error('Branch checkout failed (non-fatal):', e);
            }
        } else {
            console.warn('No workingDir configured — skipping branch checkout');
        }

        // Step 4: Download Bitrise iOS simulator build artifact
        var appPath = null;
        if (customParams.bitriseBuild) {
            var featureBranch = findFeatureBranch(ticketKey, customParams.featurePR);

            // Resolve environment-specific config if available
            var envResolution = setupHelpers.resolveEnvironmentBuildConfig(
                customParams.bitriseBuild, customParams.testEnvironment || 'prod');
            var buildConfig = envResolution.buildConfig;
            if (envResolution.active) {
                console.log('🌍 Using environment:', envResolution.environment);
                // Write environment info for the agent prompt
                var envLines = setupHelpers.buildEnvironmentMarkdown(
                    envResolution.environment, buildConfig.workflowId, envResolution.envConfig);
                file_write(folder + '/environment.md', envLines.join('\n'));
                console.log('✅ Written environment.md for', envResolution.environment);
            }

            appPath = downloadBitriseApp(ticketKey, folder, buildConfig, featureBranch, config.workingDir);
        }

        // Resolve appId from environment config
        var resolvedAppId = setupHelpers.decideAppId(
            customParams.bitriseBuild, customParams.testEnvironment || 'prod');

        // Step 5: Install app on the already-booted simulator
        if (appPath) {
            installAppOnSimulator(appPath, folder, resolvedAppId);
        }

        console.log('✅ Mobile test automation setup complete for', ticketKey);

    } catch (error) {
        console.error('❌ Error in preCliMobileTestAutomationSetup:', error);
        throw error;
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Pre-CLI Story Test Automation Setup Action
 * 1. Fetches all linked Test Cases for the Story.
 * 2. Writes input/{STORY_KEY}/linked_test_cases.json and .md.
 * 3. Checks out test/{STORY_KEY} branch and keeps it synced with origin/main:
 *    - if the branch was already merged → delete it and recreate from fresh main;
 *    - if it has unmerged test work → merge origin/main into it;
 *    - on merge conflicts → write merge_conflicts.md + pr_diff.txt so the agent can resolve them.
 */

var configLoader = require('./configLoader.js');
var prHelper = require('./common/pullRequest.js');
var scmModule = require('./common/scm.js');
var gh = require('./common/githubHelpers.js');
const { STATUSES, resolveStatuses } = require('./config.js');
var trackersModule = require('./common/trackers.js');

// Canonical copy (gh-823/gh-912): the warning:/note: line filter lives in
// common/pullRequest.js once — this delegate keeps every local call site.
function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

var MAX_DISCUSSION_THREADS = 100;

function trimDiscussionsMarkdown(markdown, maxThreads) {
    if (!markdown || maxThreads <= 0) return markdown;
    var marker = '\n### Thread ';
    var idx = markdown.indexOf(marker);
    if (idx === -1) return markdown;
    var header = markdown.substring(0, idx);
    var rest = markdown.substring(idx + marker.length);
    var sections = rest.split(marker);
    if (sections.length <= maxThreads) return markdown;
    var kept = sections.slice(sections.length - maxThreads);
    return header + marker + kept.join(marker);
}

function runGit(command, workingDir) {
    var args = { command: command };
    if (workingDir) args.workingDirectory = workingDir;
    return cli_execute_command(args);
}

function writeBranchConflictGuidance(storyKey, branchName, baseBranch, details) {
    try {
        file_write({
            path: 'input/' + storyKey + '/merge_conflicts.md',
            content: '# Branch Conflict Guidance\n\n' +
                'Branch `' + branchName + '` has test automation work that is not already merged into `origin/' + baseBranch + '`, ' +
                'and `origin/' + baseBranch + '` is not an ancestor of this branch.\n\n' +
                'Before editing tests, sync the branch deliberately with `origin/' + baseBranch + '`. ' +
                'In most cases, prefer `origin/' + baseBranch + '` for repository setup, generated workflow/config files, ' +
                'and shared infrastructure, then re-apply only the ticket-specific test automation that is still relevant.\n\n' +
                'Do not discard test files that are still needed for this ticket. Do not keep stale bootstrap/setup files just because they exist on the old branch.\n\n' +
                'Details:\n\n```\n' + (details || '(not available)') + '\n```\n'
        });
    } catch (e) {
        console.warn('Could not write branch conflict guidance:', e);
    }
}

function isAncestorRef(ancestor, descendant, workingDir) {
    try {
        var output = cleanCommandOutput(
            runGit('git rev-list -1 ' + ancestor + ' --not ' + descendant, workingDir) || ''
        );
        return output.trim() === '';
    } catch (e) {
        console.warn('Could not inspect branch ancestry for ' + ancestor + ' -> ' + descendant + ':', e);
        return false;
    }
}

function alignBranchWithBase(storyKey, branchName, baseBranch, workingDir, inputFolder) {
    // Make sure remote refs are fresh before any merge/ancestor decision —
    // targeted: just this branch and its base (owner rule 2026-10-03).
    try {
        var targetedFetch = prHelper.buildTargetedOriginFetchCommand([branchName, baseBranch]);
        if (targetedFetch) runGit(targetedFetch, workingDir);
    } catch (e) {
        console.warn('Could not fetch remote branches during align:', e);
    }

    var localExists = cleanCommandOutput(
        runGit('git branch --list "' + branchName + '"', workingDir) || ''
    ).trim() !== '';
    var remoteExists = false;
    try {
        // gh-912: decide on a real refs/heads/<branch> ref line — a
        // warning-only capture (central-mode insteadOf origin, git ≥ 2.54)
        // must classify as "branch absent".
        remoteExists = prHelper.remoteBranchExists(runGit, workingDir, branchName);
    } catch (e) {
        console.warn('Error checking remote branches:', e);
    }

    if (!localExists && !remoteExists) {
        console.log('Creating new test branch from', baseBranch + ':', branchName);
        runGit('git checkout ' + baseBranch, workingDir);
        runGit('git pull origin ' + baseBranch, workingDir);
        runGit('git checkout -b ' + branchName, workingDir);
        return;
    }

    if (!localExists && remoteExists) {
        console.log('Checking out remote test branch:', branchName);
        runGit('git checkout -b ' + branchName + ' origin/' + branchName, workingDir);
    } else {
        console.log('Switching to existing local test branch:', branchName);
        runGit('git checkout ' + branchName, workingDir);
    }

    // Case 1: the test branch has already been merged into main.
    // Drop the stale branch (local + remote) and create a fresh one from main.
    if (isAncestorRef('HEAD', 'origin/' + baseBranch, workingDir)) {
        console.log('Test branch ' + branchName + ' is already merged into origin/' + baseBranch + '; recreating from fresh ' + baseBranch);
        runGit('git checkout ' + baseBranch, workingDir);
        try {
            runGit('git branch -D ' + branchName, workingDir);
        } catch (e) {
            console.warn('Could not delete local test branch:', e);
        }
        try {
            runGit('git push origin --delete ' + branchName, workingDir);
        } catch (e) {
            console.warn('Could not delete remote test branch:', e);
        }
        runGit('git pull origin ' + baseBranch, workingDir);
        runGit('git checkout -b ' + branchName, workingDir);
        return;
    }

    // Case 2: branch has unmerged test work — always pull main into it.
    console.log('Merging origin/' + baseBranch + ' into test branch ' + branchName);
    var conflictFiles = gh.detectMergeConflicts(baseBranch, inputFolder, workingDir);
    if (conflictFiles.length > 0) {
        console.warn('⚠️ Merge conflicts detected after pulling origin/' + baseBranch + ':', conflictFiles.join(', '));
        try {
            var diff = gh.getPRDiff(baseBranch, branchName, workingDir);
            if (diff) {
                file_write({
                    path: inputFolder + '/pr_diff.txt',
                    content: gh.trimLargeTextForInput(diff, 'PR Diff', 12000)
                });
                console.log('✅ Wrote pr_diff.txt for conflict resolution');
            }
        } catch (e) {
            console.warn('Could not write pr_diff.txt:', e);
        }
        writeBranchConflictGuidance(
            storyKey,
            branchName,
            baseBranch,
            'Merge conflicts after pulling origin/' + baseBranch + ' into ' + branchName + ':\n\n' +
            conflictFiles.map(function(f) { return '* ' + f; }).join('\n') + '\n\n' +
            'Resolve conflicts, stage the files, and continue. The post-action will commit and push the resolved test code.'
        );
    } else {
        console.log('✅ Merged origin/' + baseBranch + ' cleanly into test branch ' + branchName);
    }
}

function checkoutBranch(storyKey, config, inputFolder) {
    var branchName = configLoader.formatBranchName(config.git.branchPrefix.test, storyKey);
    var workingDir = config.workingDir || null;
    console.log('Setting up branch:', branchName);

    try {
        runGit('git config user.name "' + config.git.authorName + '"', workingDir);
        runGit('git config user.email "' + config.git.authorEmail + '"', workingDir);
    } catch (e) {
        console.warn('Failed to configure git author:', e);
    }

    try {
        var setupFetch = prHelper.buildTargetedOriginFetchCommand([branchName, config.git.baseBranch]);
        if (setupFetch) runGit(setupFetch, workingDir);
    } catch (e) {
        console.warn('Could not fetch remote branches:', e);
    }

    alignBranchWithBase(storyKey, branchName, config.git.baseBranch, workingDir, inputFolder);

    console.log('✅ Branch ready:', branchName);
}

function fetchLinkedTestCases(storyKey, testCaseType, tracker) {
    var jql = 'issue in linkedIssues("' + storyKey + '") AND issuetype = "' + testCaseType + '"';
    console.log('Fetching linked Test Cases with JQL:', jql);
    try {
        // JQL text: provider-specific query (WIQL on ado)
        var results = tracker.searchIssues(jql, { maxResults: 100, fields: ['key', 'summary', 'status'] });
        return Array.isArray(results) ? results : [];
    } catch (e) {
        console.warn('Failed to fetch linked Test Cases:', e);
        return [];
    }
}

function renderTestCase(tc) {
    var fields = tc.fields || {};
    var lines = [];
    lines.push('- ' + tc.key + ' — ' + (fields.summary || '(no summary)') +
               ' [' + (fields.status && fields.status.name ? fields.status.name : 'Unknown') + ']');
    return lines.join('\n');
}

function writeLinkedTestCases(storyKey, testCases) {
    var inputDir = 'input/' + storyKey;
    try {
        file_write({
            path: inputDir + '/linked_test_cases.json',
            content: JSON.stringify({ storyKey: storyKey, testCases: testCases }, null, 2)
        });
    } catch (e) {
        console.warn('Could not write linked_test_cases.json:', e);
    }

    var md = '# Linked Test Cases for ' + storyKey + '\n\n';
    md += 'Total: ' + testCases.length + '\n\n';
    testCases.forEach(function(tc) {
        md += renderTestCase(tc) + '\n';
    });
    md += '\n';

    try {
        file_write({
            path: inputDir + '/linked_test_cases.md',
            content: md
        });
    } catch (e) {
        console.warn('Could not write linked_test_cases.md:', e);
    }
}

function findTestPr(scm, storyKey, config) {
    try {
        var branchName = configLoader.formatBranchName(config.git.branchPrefix.test, storyKey);
        var openPRs = scm.listPrs('open') || [];
        return openPRs.find(function(pr) {
            return pr.head && pr.head.ref && pr.head.ref === branchName;
        }) || null;
    } catch (e) {
        console.warn('Could not list open PRs for test branch:', e);
        return null;
    }
}

// ── gh-930: writePrContext split into formatting helpers ────────────────────
// Every helper is source-agnostic: it only consumes the scm abstraction
// (getPrDiff / fetchDiscussions) and the PR object shape, so GitHub, GitLab
// and ADO PRs flow through the same code paths.

function prUserLogin(pr) {
    return pr.user && pr.user.login ? pr.user.login : '';
}

function prBranchPair(pr) {
    return '`' + (pr.head && pr.head.ref ? pr.head.ref : '') + '` → `' + (pr.base && pr.base.ref ? pr.base.ref : '') + '`';
}

function buildPrInfoMarkdown(pr) {
    return '# Pull Request Information\n' +
        '- **PR #**: ' + (pr.number || '') + '\n' +
        '- **URL**: ' + (pr.html_url || '') + '\n' +
        '- **Title**: ' + (pr.title || '') + '\n' +
        '- **Author**: ' + prUserLogin(pr) + '\n' +
        '- **Branch**: ' + prBranchPair(pr) + '\n' +
        '- **State**: ' + (pr.state || '') + '\n';
}

function writePrInfo(inputDir, pr) {
    try {
        file_write({ path: inputDir + '/pr_info.md', content: buildPrInfoMarkdown(pr) });
        console.log('✅ Wrote pr_info.md for PR #' + pr.number);
    } catch (e) {
        console.warn('Could not write pr_info.md:', e);
    }
}

function writePrDiff(inputDir, scm, pr) {
    try {
        var diff = scm.getPrDiff(pr.number);
        if (diff) {
            file_write({ path: inputDir + '/pr_diff.txt', content: diff });
            console.log('✅ Wrote pr_diff.txt (' + diff.length + ' chars)');
        }
    } catch (e) {
        console.warn('Could not write pr_diff.txt:', e);
    }
}

function writePrDiscussionsMarkdown(inputDir, discussions) {
    if (!discussions || !discussions.markdown) return;
    var trimmedMarkdown = trimDiscussionsMarkdown(discussions.markdown, MAX_DISCUSSION_THREADS);
    if (trimmedMarkdown !== discussions.markdown) {
        console.warn('⚠️ PR discussions markdown truncated from full history to last ' + MAX_DISCUSSION_THREADS + ' threads to keep agent context bounded');
    }
    file_write({ path: inputDir + '/pr_discussions.md', content: trimmedMarkdown });
    console.log('✅ Wrote pr_discussions.md');
}

function openThreadReplies(rawThreads) {
    var threads = rawThreads.threads;
    if (threads.length > MAX_DISCUSSION_THREADS) {
        console.warn('⚠️ PR discussions raw threads truncated from ' + threads.length + ' to last ' + MAX_DISCUSSION_THREADS + ' for review replies');
        threads = threads.slice(threads.length - MAX_DISCUSSION_THREADS);
    }
    return threads
        .filter(function(t) { return !t.resolved && t.body; })
        .map(function(t) {
            return {
                file: t.path,
                line: t.line,
                comment: t.body,
                severity: 'important',
                threadId: t.threadId || t.id || null,
                inReplyToId: t.rootCommentId || t.id || null
            };
        });
}

function writeReviewReplies(replies) {
    if (replies.length > 0) {
        file_write({ path: 'outputs/review_replies.json', content: JSON.stringify({ replies: replies }, null, 2) });
        console.log('✅ Wrote outputs/review_replies.json with', replies.length, 'open review thread(s)');
    }
}

function writePrDiscussions(inputDir, discussions) {
    writePrDiscussionsMarkdown(inputDir, discussions);
    if (discussions && discussions.rawThreads && discussions.rawThreads.threads) {
        writeReviewReplies(openThreadReplies(discussions.rawThreads));
    }
}

function writePrContext(storyKey, scm, pr) {
    var inputDir = 'input/' + storyKey;
    writePrInfo(inputDir, pr);
    writePrDiff(inputDir, scm, pr);
    try {
        writePrDiscussions(inputDir, scm.fetchDiscussions(pr.number));
    } catch (e) {
        console.warn('Could not write PR discussions:', e);
    }
}

function getTestCaseDirectory(tcKey, testFilesPath) {
    var basePath = (testFilesPath || 'testing/').replace(/\/$/, '');
    return basePath + '/tests/' + tcKey;
}

// ── gh-1192: removeIrrelevantTestCode split into a per-TC helper ────────────

/**
 * Remove the tracked test code of ONE TC whose status marks it irrelevant.
 * Mutates `removed` (collected in list order); every failure is a warn that
 * skips just this TC.
 */
function removeTestCodeForIrrelevantTc(tc, workingDir, testFilesPath, irrelevantStatus, removed) {
    var status = tc.fields && tc.fields.status && tc.fields.status.name;
    if (status !== irrelevantStatus) return;
    var dir = getTestCaseDirectory(tc.key, testFilesPath);
    try {
        var lsOutput = cleanCommandOutput(runGit('git ls-files -- ' + dir, workingDir) || '');
        if (!lsOutput.trim()) {
            console.log('No tracked test code to remove for irrelevant TC:', tc.key);
            return;
        }
        console.log('Removing test code for irrelevant TC:', tc.key, '—', dir);
        runGit('git rm -r --ignore-unmatch -- ' + dir, workingDir);
        removed.push(tc.key);
    } catch (e) {
        console.warn('Failed to remove test code for irrelevant TC', tc.key, ':', e);
    }
}

function removeIrrelevantTestCode(testCases, workingDir, testFilesPath, irrelevantStatus) {
    var removed = [];
    testCases.forEach(function(tc) {
        removeTestCodeForIrrelevantTc(tc, workingDir, testFilesPath, irrelevantStatus, removed);
    });
    return removed;
}

// ── gh-1192: action() split into a context builder + per-step executors ─────

/** The Test Case issue type configured for the project (default 'Test Case'). */
function testCaseTypeOf(projectConfig) {
    return projectConfig.jira && projectConfig.jira.issueTypes && projectConfig.jira.issueTypes.TEST_CASE
        ? projectConfig.jira.issueTypes.TEST_CASE
        : 'Test Case';
}

/** Everything the setup steps need, resolved once, in the original order. */
function resolveSetupContext(params) {
    var actualParams = params.inputFolderPath ? params : (params.jobParams || params);
    var folder = actualParams.inputFolderPath;
    var storyKey = folder.split('/').pop();
    var config = configLoader.loadProjectConfig(params.jobParams || params);
    var projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
    var customParams = (params.jobParams || params).customParams || {};
    return {
        actualParams: actualParams,
        folder: folder,
        storyKey: storyKey,
        config: config,
        projectConfig: projectConfig,
        testCaseType: testCaseTypeOf(projectConfig),
        customParams: customParams,
        tracker: trackersModule.createTracker(projectConfig, customParams),
        statuses: resolveStatuses(customParams),
        testFilesPath: customParams.testFilesGlob || 'testing/'
    };
}

/** Step 1: fetch the linked Test Cases and write the input context files. */
function stepFetchLinkedTestCases(ctx) {
    var testCases = fetchLinkedTestCases(ctx.storyKey, ctx.testCaseType, ctx.tracker);
    console.log('Found', testCases.length, 'linked Test Case(s)');

    if (testCases.length === 0) {
        console.warn('No linked Test Cases found for Story', ctx.storyKey);
    }

    writeLinkedTestCases(ctx.storyKey, testCases);
    return testCases;
}

/** Step 2: checkout test/{STORY_KEY} synced with the base branch (non-fatal). */
function stepCheckoutTestBranch(ctx) {
    try {
        checkoutBranch(ctx.storyKey, ctx.config, ctx.folder);
    } catch (e) {
        console.error('Branch checkout failed (non-fatal):', e);
    }
}

/** Step 3: fetch PR context for rework when an open test PR exists (non-fatal). */
function stepWriteTestPrContext(ctx) {
    try {
        var scm = scmModule.createScm(ctx.projectConfig);
        var pr = findTestPr(scm, ctx.storyKey, ctx.config);
        if (pr && pr.number) {
            console.log('Open test PR found:', pr.number, '— fetching diff and discussions');
            writePrContext(ctx.storyKey, scm, pr);
        } else {
            console.log('No open test PR found for', ctx.storyKey);
        }
    } catch (e) {
        console.warn('Fetching PR context failed (non-fatal):', e);
    }
}

/** Step 4: remove test code for linked TCs marked Irrelevant (non-fatal). */
function stepRemoveIrrelevantTestCode(ctx, testCases) {
    try {
        var removed = removeIrrelevantTestCode(testCases, ctx.config.workingDir || null, ctx.testFilesPath, ctx.statuses.IRRELEVANT || 'Irrelevant');
        if (removed.length > 0) {
            console.log('Removed test code for irrelevant TCs:', removed.join(', '));
        }
    } catch (e) {
        console.warn('Removing irrelevant test code failed (non-fatal):', e);
    }
}

function action(params) {
    try {
        var ctx = resolveSetupContext(params);

        console.log('=== Story test automation setup for:', ctx.storyKey, '===');

        var testCases = stepFetchLinkedTestCases(ctx);
        stepCheckoutTestBranch(ctx);
        stepWriteTestPrContext(ctx);
        stepRemoveIrrelevantTestCode(ctx, testCases);

        console.log('✅ Story test automation setup complete for', ctx.storyKey);

    } catch (error) {
        console.error('❌ Error in preCliStoryTestAutomationSetup:', error);
        return { success: false, error: error.toString() };
    }

    return { success: true };
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        // gh-1192: extracted setup/removal helpers (test surface)
        removeIrrelevantTestCode: removeIrrelevantTestCode,
        removeTestCodeForIrrelevantTc: removeTestCodeForIrrelevantTc,
        getTestCaseDirectory: getTestCaseDirectory,
        testCaseTypeOf: testCaseTypeOf
    };
}

/**
 * Post Mobile Test Automation Results (generic postJSAction)
 *
 * Designed for story/bug trigger tickets that run mobile automated tests.
 * Handles git operations on the test automation repo, creates the automation PR,
 * labels and updates the feature PR, and posts results to Jira.
 *
 * Steps:
 * 1. If mandatory output files are missing, attempt one resume run via run-agent.sh --continue
 * 2. Read outputs/test_automation_result.json
 * 3. Commit + push test files in the automation repo (src/tests/)
 * 4. Create or find PR in the test automation repository
 * 5. Find the feature PR in the main app repository (by trigger ticket key)
 * 6. Add configurable pass/fail labels to the feature PR/MR
 * 7. Append test summary to the feature PR/MR as a comment
 * 8. Post Jira comment on the trigger ticket
 * 9. Move trigger ticket status (Passed / Failed / Blocked)
 * 10. Remove WIP and SM trigger labels
 *
 * Configuration (via customParams):
 *   targetRepository.workingDir   — path to test automation repo (required)
 *   targetRepository.baseBranch   — base branch (default: main)
 *   featurePR.owner               — GitHub owner for the feature repo (required)
 *   featurePR.repo                — GitHub repo name for the feature repo (required)
 *   labels.testsPassed            — label to add on pass (default: tests_passed)
 *   labels.testsFailed            — label to add on fail (default: tests_failed)
 *   testFilesGlob                 — git add path for test files (default: src/tests/)
 *   removeLabel                   — SM trigger label to remove after completion
 */

var configLoader = require('./configLoader.js');
const { LABELS } = require('./config.js');
var prHelper = require('./common/pullRequest.js');
var outputFiles = require('./common/outputFiles.js');
var trackersModule = require('./common/trackers.js');
var mobileHelpers = require('./postMobileTestAutomationResultsHelpers.js');
// Tracker-agnostic ticket ops; created inside action() (never at module load).
var tracker = null;

/** Marker file path to prevent infinite resume loops. */
var RESUME_MARKER = 'outputs/.missing-output-resume-attempted';

function createScmCompat(config, owner, repo) {
    var scopedConfig = Object.assign({}, config || {});
    if (owner && repo) {
        scopedConfig.repository = { owner: owner, repo: repo };
    }
    try {
        return configLoader.createScm(scopedConfig);
    } catch (e) {
        console.warn('SCM abstraction unavailable, falling back to GitHub globals:', e.message || e);
        return {
            listPrs: function(state) {
                var raw = github_list_prs({ workspace: owner, repository: repo, state: state });
                var parsed = parseMcpResult(raw);
                return Array.isArray(parsed) ? parsed : (parsed && parsed.data ? parsed.data : []);
            },
            addLabel: function(prNumber, label) {
                return github_add_pr_label({ workspace: owner, repository: repo, pullRequestId: String(prNumber), label: label });
            },
            removeLabel: function(prNumber, label) {
                return github_remove_pr_label({ workspace: owner, repository: repo, pullRequestId: String(prNumber), label: label });
            },
            addComment: function(prNumber, text) {
                return github_add_pr_comment({ workspace: owner, repository: repo, pullRequestId: String(prNumber), text: text });
            }
        };
    }
}

/**
 * If mandatory output files are missing and a resume has not already been attempted,
 * run `run-agent.sh --continue` with a targeted recovery prompt so the agent
 * writes outputs/test_automation_result.json, outputs/response.md, outputs/pr_body.md,
 * and outputs/pr_feature_update.md without rewriting the already-committed flows.
 *
 * Returns true if a resume was executed (caller should re-check outputs afterwards).
 * Returns false if outputs already exist, or a resume was already attempted.
 */
function attemptResumeIfOutputsMissing(ticketKey, workingDir) {
    var resultJson = readOutputFile('test_automation_result.json', workingDir, ticketKey);
    if (resultJson) {
        return false; // outputs present — no resume needed
    }

    // Guard against infinite loops
    var alreadyAttempted = readOutputFile(RESUME_MARKER, workingDir, ticketKey);
    if (alreadyAttempted) {
        console.warn('⚠️  Resume already attempted once — skipping second resume to avoid infinite loop');
        return false;
    }

    console.log('⚠️  Mandatory output files missing. Attempting resume run to write outputs…');

    // Write marker first so the resumed run cannot trigger another resume
    try {
        file_write(RESUME_MARKER, new Date().toISOString() + '\n');
    } catch (e) {
        console.warn('Could not write resume marker:', e);
    }

    var recoveryPrompt =
        'RESUME TASK: The previous automation run ended before writing the mandatory output files.\n\n' +
        'DO NOT rewrite or delete existing flows. Inspect git changes, app_info.md, and any Maestro run logs first.\n' +
        'If the generated suite has NOT been executed and app_info.md provides APP_PATH/MAESTRO_DEVICE,\n' +
        'run the generated suite once on the available simulator before writing results. Use the suite file\n' +
        'under src/flows/suites/ when present. Only mark flows as "written" when there is a real blocker\n' +
        'that prevents simulator execution, and explain that blocker in the summary.\n\n' +
        'Then write the four output files:\n\n' +
        '1. /Users/vagrant/git/outputs/test_automation_result.json\n' +
        '   Schema: { "status":"passed"|"failed", "passed":N, "failed":N, "skipped":N, "summary":"…",\n' +
        '     "results":[{ "ticket":"PROJ-XXXX", "status":"passed"|"failed"|"written"|"skipped",\n' +
        '       "title":"…", "file":"src/flows/…" }] }\n' +
        '   Mark any flow that was WRITTEN but not run as "status":"written" only when simulator execution was impossible.\n\n' +
        '2. /Users/vagrant/git/outputs/response.md\n' +
        '   Jira-flavoured markdown (h3 header, Jira table with || pipes) summarising per-TC results.\n\n' +
        '3. /Users/vagrant/git/outputs/pr_body.md\n' +
        '   GitHub-flavoured markdown version of response.md (| tables, **bold**).\n\n' +
        '4. /Users/vagrant/git/outputs/pr_feature_update.md\n' +
        '   Compact summary for the feature PR (same format as pr_body.md but shorter).\n\n' +
        'After writing all four files, verify they exist:\n' +
        '```bash\n' +
        'ls -la /Users/vagrant/git/outputs/\n' +
        'cat /Users/vagrant/git/outputs/test_automation_result.json\n' +
        '```\n\n' +
        'Do NOT log out or install the app unless app_info.md explicitly requires it.\n' +
        'Ticket: ' + ticketKey + '\n';

    var promptFile = 'outputs/.resume-prompt.md';
    try {
        file_write(promptFile, recoveryPrompt);
    } catch (e) {
        console.error('Failed to write resume prompt file:', e);
        return false;
    }

    try {
        var resumeResult = cli_execute_command({
            // `--continue` alone resumes the most recent session in this directory;
            // pairing it with `--resume` is rejected by the Copilot CLI as mutually
            // exclusive ("cannot be used with option '--continue'"), which made this
            // recovery run fail deterministically before ever reaching the agent.
            command: 'bash agents/scripts/run-agent.sh --continue ' + promptFile
        });
        console.log('Resume run output:', (resumeResult || '').substring(0, 500));
        return true;
    } catch (e) {
        console.error('Resume run failed:', e);
        return false;
    }
}

function parseMcpResult(result) {
    if (!result) return null;
    if (typeof result === 'string') {
        try { return JSON.parse(result); } catch (e) { return null; }
    }
    return result;
}

function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

function readFile(path) {
    return outputFiles.readOutputFile(path, {});
}

/** Read an output file from normalized paths (root outputs, ticket subdir, and workingDir variants). */
function readOutputFile(relativePath, workingDir, ticketKey) {
    return outputFiles.readOutputFile(relativePath, {
        workingDir: workingDir,
        ticketKey: ticketKey
    });
}

function readResultJson(workingDir, ticketKey) {
    var raw = readOutputFile('test_automation_result.json', workingDir, ticketKey);
    if (!raw) {
        console.warn('test_automation_result.json not found in outputs/ or ' + (workingDir || 'no') + '/outputs/');
        return null;
    }
    try {
        var parsed = JSON.parse(raw);
        parsed = normalizeResult(parsed);
        console.log('✅ Read test result — status:', parsed.status);
        return parsed;
    } catch (e) {
        console.error('Failed to parse test_automation_result.json:', e);
        return null;
    }
}

function asNumber(value) {
    if (value === undefined || value === null || value === '') return null;
    var n = parseInt(value, 10);
    return isNaN(n) ? null : n;
}

function firstNumber(obj, keys) {
    for (var i = 0; i < keys.length; i++) {
        var value = asNumber(obj && obj[keys[i]]);
        if (value !== null) return value;
    }
    return null;
}

function getResultCounts(result) {
    var counts = {
        passed: firstNumber(result, ['passed', 'passedCount', 'passed_count', 'passedTests', 'passed_tests']),
        failed: firstNumber(result, ['failed', 'failedCount', 'failed_count', 'failedTests', 'failed_tests']),
        skipped: firstNumber(result, ['skipped', 'skippedCount', 'skipped_count', 'skippedTests', 'skipped_tests'])
    };

    if (result && result.results && Array.isArray(result.results)) {
        counts = mobileHelpers.mergeFallbackCounts(counts, mobileHelpers.countResultStatuses(result.results));
    }

    return mobileHelpers.finalizeCounts(counts);
}

function normalizeResult(result) {
    result = result || {};
    if (!result.status) {
        var counts = getResultCounts(result);
        var passRate = String(result.passRate || result.pass_rate || '').trim();
        if (counts.failed > 0) {
            result.status = 'failed';
        } else if (counts.passed > 0 || passRate === '100%' || passRate === '100') {
            result.status = 'passed';
        } else if (result.results && Array.isArray(result.results) && result.results.length > 0) {
            result.status = 'failed';
        }
    }
    return result;
}

/** Run a command inside the automation repo directory. */
function runInRepo(command, workingDir) {
    return cli_execute_command({ command: command, workingDirectory: workingDir });
}

/** Sanitize text for use in shell command arguments such as git commit messages.
 *  CliCommandExecutor rejects commands containing shell metacharacters: ; \n \r ` $() ${} && || | > <
 *  Jira titles often contain -> (arrows), <angle brackets>, etc.  */
function sanitizeForShell(text) {
    return (text || '')
        .replace(/->/g, '→').replace(/<-/g, '←')
        .replace(/[<>|&;$`]/g, ' ')
        .replace(/\s{2,}/g, ' ')
        .trim();
}

/** Push the branch (with --force) when it does not exist on origin yet. */
function ensureRemoteBranch(branchName, workingDir) {
    // Ensure branch exists on remote so PR can be created/found
    var remoteBranchExists = false;
    try {
        // gh-912: decide on a real refs/heads/<branch> ref line — a
        // warning-only capture (central-mode insteadOf origin, git
        // ≥ 2.54) must classify as "branch absent" so the push runs.
        remoteBranchExists = prHelper.remoteBranchExists(runInRepo, workingDir, branchName);
    } catch (lsRemoteErr) {
        console.warn('Error checking remote branches:', lsRemoteErr);
    }
    if (!remoteBranchExists) {
        runInRepo('git push -u origin ' + branchName + ' --force', workingDir);
    }
}

/** Commit staged changes and push; falls back to a forced push. */
function commitAndPush(branchName, commitMessage, workingDir) {
    runInRepo('git commit -m "' + prHelper.sanitizeCommitMessage(commitMessage) + '"', workingDir);

    try {
        runInRepo('git push -u origin ' + branchName, workingDir);
    } catch (e) {
        runInRepo('git push -u origin ' + branchName + ' --force', workingDir);
    }
}

/** Commit + push test files in the automation repo. */
function performGitOperations(branchName, commitMessage, workingDir, testFilesPath) {
    var addPath = testFilesPath || 'src/tests/';
    try {
        runInRepo('git add ' + addPath, workingDir);

        var stagedOutput = cleanCommandOutput(
            runInRepo('git diff --cached --stat', workingDir) || ''
        );
        console.log('Staged changes:', stagedOutput || '(none)');

        if (mobileHelpers.decideNoStagedChanges(stagedOutput)) {
            console.warn('No new staged changes in', addPath);
            ensureRemoteBranch(branchName, workingDir);
            return { success: true, branchName: branchName, noNewCommit: true };
        }

        commitAndPush(branchName, commitMessage, workingDir);

        console.log('✅ Git operations completed');
        return { success: true, branchName: branchName };

    } catch (error) {
        console.error('Git operations failed:', error);
        return { success: false, error: error.toString() };
    }
}

/** Create PR in the automation repo (or find existing). */
function createAutomationPR(title, branchName, baseBranch, workingDir, scm, ticketKey) {
    var result = prHelper.createPullRequest({
        title: title,
        branchName: branchName,
        baseBranch: baseBranch,
        workingDir: workingDir,
        scm: scm,
        // gh-737: merge bot links approved issues via 'Closes #N' — emit it
        // by construction on every automation PR.
        ticketKey: ticketKey,
        runCommand: runInRepo,
        readFile: function(path) { return readOutputFile(path, workingDir, null); },
        writeFile: file_write,
        bodyFileCandidates: ['outputs/pr_body.md', 'outputs/response.md'],
        defaultBody: 'Automated test flows'
    });
    if (result.success) console.log('✅ Automation PR:', result.prUrl || '(URL not found)');
    return result;
}

/**
 * Find the feature PR/MR in the main app repo by trigger ticket key.
 */
function findFeaturePR(ticketKey, scm, owner, repo) {
    try {
        var raw = scm.listPrs('open');
        var parsed = parseMcpResult(raw);
        var prs = Array.isArray(parsed) ? parsed : (parsed && parsed.data ? parsed.data : []);

        if (!prs || prs.length === 0) {
            console.log('No open PRs found in', owner + '/' + repo);
            return null;
        }

        for (var i = 0; i < prs.length; i++) {
            var pr = prs[i];
            var prTitle = pr.title || '';
            var prBranch = (pr.head && pr.head.ref) || '';
            if (prTitle.indexOf(ticketKey) !== -1 || prBranch.indexOf(ticketKey) !== -1) {
                console.log('✅ Found feature PR #' + pr.number + ': ' + prTitle + ' (' + prBranch + ')');
                return pr;
            }
        }

        console.log('No feature PR found matching', ticketKey, 'in', owner + '/' + repo);
        return null;
    } catch (e) {
        console.warn('Failed to find feature PR:', e);
        return null;
    }
}

/** Add the appropriate result label to the feature PR, removing the opposite one. */
function updateFeaturePRLabel(owner, repo, prNumber, passed, labelPassed, labelFailed) {
    var labels = mobileHelpers.decideFeaturePrLabels(passed, labelPassed, labelFailed);
    var addLabel = labels.addLabel;
    var removeLabel = labels.removeLabel;

    try {
        try {
            github_remove_pr_label({ workspace: owner, repository: repo, pullRequestId: String(prNumber), label: removeLabel });
        } catch (_) {}

        github_add_pr_label({ workspace: owner, repository: repo, pullRequestId: String(prNumber), label: addLabel });
        console.log('✅ Added label "' + addLabel + '" to feature PR #' + prNumber);
    } catch (e) {
        console.warn('Failed to update feature PR label:', e);
    }
}

function updateFeaturePRLabelWithScm(scm, prNumber, passed, labelPassed, labelFailed) {
    var labels = mobileHelpers.decideFeaturePrLabels(passed, labelPassed, labelFailed);
    var addLabel = labels.addLabel;
    var removeLabel = labels.removeLabel;

    try {
        try { scm.removeLabel(prNumber, removeLabel); } catch (_) {}
        scm.addLabel(prNumber, addLabel);
        console.log('✅ Added label "' + addLabel + '" to feature PR/MR #' + prNumber);
    } catch (e) {
        console.warn('Failed to update feature PR/MR label:', e);
    }
}

/** Post test result summary as a comment on the feature PR. */
function buildFeatureVerdictSummary(result) {
    var counts = getResultCounts(result || {});
    var status = String((result && result.status) || '').toLowerCase();
    var verdict = status === 'passed'
        ? '✅ FIX VERIFIED — Maestro suite passed'
        : status === 'blocked_by_human'
        ? '🚫 BLOCKED — test automation needs human setup'
        : '❌ FIX FAILED — Maestro suite failed';
    return '## 🤖 Maestro Test Results\n\n' +
        '**Verdict**: ' + verdict + '\n\n' +
        '| Passed | Failed | Skipped |\n' +
        '|--------|--------|---------|\n' +
        '| ' + counts.passed + ' | ' + counts.failed + ' | ' + counts.skipped + ' |\n\n';
}

function updateFeaturePRBody(owner, repo, prNumber, workingDir, result, ticketKey) {
    var summary = mobileHelpers.resolveFeatureSummary(function(path) {
        return readOutputFile(path, workingDir, ticketKey);
    });
    if (!summary) {
