#!/usr/bin/env node
// Print uncovered statements/branches for a given source file from Istanbul coverage.
'use strict';
const cov = require('/tmp/cov/coverage-final.json');
const file = process.argv[2];
const fs = require('fs');
const key = Object.keys(cov).find(k => k.endsWith('/' + file));
if (!key) { console.error('no coverage for', file); process.exit(1); }
const e = cov[key];
const src = fs.readFileSync('/home/runner/work/dmtools-agents/dmtools-agents/js/' + file, 'utf8').split('\n');
const line = (loc) => loc.start.line;

// Uncovered statements
const uncoveredStmts = [];
for (const [id, n] of Object.entries(e.s)) {
  if (n === 0) uncoveredStmts.push(e.statementMap[id]);
}
// Branches: each branch has an array of paths with counts
const uncoveredBranches = [];
for (const [id, counts] of Object.entries(e.b)) {
  const bm = e.branchMap[id];
  counts.forEach((n, i) => {
    if (n === 0) {
      const loc = (bm.locations && bm.locations[i]) || bm.loc;
      uncoveredBranches.push({ type: bm.type, loc });
    }
  });
}
// Functions never called
const uncoveredFns = [];
for (const [id, n] of Object.entries(e.f)) {
  if (n === 0) uncoveredFns.push(e.fnMap[id]);
}

const fmt = (loc) => `L${line(loc)}`;
console.log('== ' + file + ' ==');
console.log('uncovered statements:', uncoveredStmts.map(fmt).join(', ') || '(none)');
console.log('uncovered fn entries:', uncoveredFns.map(fmt).join(', ') || '(none)');
console.log('uncovered branch paths:');
const byLine = {};
for (const b of uncoveredBranches) {
  const l = line(b.loc);
  (byLine[l] = byLine[l] || []).push(b.type + ':' + line(b.loc));
}
for (const l of Object.keys(byLine).sort((a, b) => a - b)) {
  console.log('  L' + l + ' → ' + src[l - 1] ? `L${l}: ${src[l-1].trim().slice(0, 110)}  [${byLine[l].join(' ')}]` : `L${l} [${byLine[l]}]`);
}

