                if (opts.command.indexOf('git branch --list') !== -1) return '  test/PROJ-5678';
                return '';
            }
        });

        m.action(makeParams('PROJ-5678', '/tmp/automation-repo'));

        var checkoutExisting = commands.find(function(c) {
