#!/usr/bin/env node
// Attributed CRAP scores for the gh-1223 target files, before vs after.
'use strict';
const fs = require('fs');
const TARGETS = [
  'js/preCliMobileTestAutomationSetup.js',
  'js/preCliStoryTestAutomationSetup.js',
  'js/postMobileTestAutomationResults.js',
  'js/preCliTestAutomationSetup.js'
];
function parseReport(path) {
  const rows = {};
  for (const line of fs.readFileSync(path, 'utf8').split('\n')) {
    const m = /^(\S+)\s+(\S+)\s+(\d+)\s+([\d.]+%|N\/A)\s+([\d.]+|N\/A)\s*$/.exec(line.trim());
    if (!m) continue;
    const [, method, file, cc, cov, crap] = m;
    if (!TARGETS.some(t => file.endsWith(t.replace('js/', 'js/')))) continue;
    if (!file.includes('/js/')) continue;
    rows[method + ' @ ' + file.split('/').pop()] = { cc: +cc, cov, crap: parseFloat(crap) };
  }
  return rows;
}
const [before, after] = [parseReport(process.argv[2]), parseReport(process.argv[3])];
const names = Array.from(new Set([...Object.keys(before), ...Object.keys(after)])).sort();
console.log('function                          | before CC/cov/CRAP        | after CC/cov/CRAP');
for (const n of names) {
  const b = before[n], a = after[n];
  const f = (x) => x ? `${x.cc} ${x.cov} ${x.crap}` : '—';
  const flag = (a && b && a.crap > b.crap + 1e-9) ? '  ⚠️ GREW' : '';
  console.log(`${n.padEnd(34)}| ${f(b).padEnd(26)}| ${f(a)}${flag}`);
}

